import random
from pathlib import Path
import matplotlib.pyplot as plt
import torch
from torchmetrics.functional import structural_similarity_index_measure

from predict import load_config, load_checkpoint, resolve_path, set_seed
from dataset import HipMRIDataset

# Code generated by ChatGPT.

def optimize_latent(G, target, latent_dim, device, steps=1000, lr=0.05):
    G.eval()
    for param in G.parameters():
        param.requires_grad_(False)

    target = target.unsqueeze(0).to(device, dtype=torch.float32)
    target_01 = ((target + 1) / 2).clamp(0, 1)

    z = torch.randn(1, latent_dim, 1, 1, device=device, requires_grad=True)
    optimizer = torch.optim.Adam([z], lr=lr)

    def get_ssim(generated):
        generated_01 = ((generated + 1) / 2).clamp(0, 1)
        return structural_similarity_index_measure(
            generated_01, target_01, data_range=1.0
        )

    with torch.no_grad():
        initial = G(z).detach()
        initial_ssim = get_ssim(initial).item() #type:ignore

    best_image = initial.clone()
    best_ssim = initial_ssim

    for step in range(steps):
        optimizer.zero_grad()

        generated = G(z)
        loss = 1 - get_ssim(generated) #type:ignore
        loss.backward()
        optimizer.step()

        with torch.no_grad():
            score = get_ssim(G(z)).item() #type:ignore
            if score > best_ssim:
                best_ssim = score
                best_image = G(z).detach().clone()

        if (step + 1) % 100 == 0:
            print(f"Step {step + 1}/{steps}: SSIM = {score:.4f}")

    print(f"Initial SSIM: {initial_ssim:.4f}")
    print(f"Best SSIM:    {best_ssim:.4f}")

    return initial, best_image, initial_ssim, best_ssim


def main():
    config = load_config()
    set_seed(config.get("seed", 42))

    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    results_dir = resolve_path(config["results_dir"])
    checkpoint_path = results_dir / "checkpoint.pth"

    G = load_checkpoint(checkpoint_path, device, config)

    dataset = HipMRIDataset(
        data_dir=config["test_dir"],
        norm_image=config.get("norm_image", True),
        week=config.get("week"),
    )

    index = random.randrange(len(dataset))
    sample = dataset[index]
    target = sample[0] if isinstance(sample, (tuple, list)) else sample

    print(f"Test image index: {index}")

    initial, optimized, initial_ssim, best_ssim = optimize_latent(
        G, target, config["latent_dim"], device
    )

    images = [target.squeeze().cpu(), initial[0, 0].cpu(),
              optimized[0, 0].cpu()]
    titles = [
        "Real target",
        f"Initial SSIM: {initial_ssim:.3f}",
        f"Optimised SSIM: {best_ssim:.3f}",
    ]

    fig, axes = plt.subplots(1, 3, figsize=(12, 4))
    for ax, image, title in zip(axes, images, titles):
        ax.imshow(image, cmap="gray", vmin=-1, vmax=1)
        ax.set_title(title)
        ax.axis("off")

    plt.tight_layout()
    output_path = results_dir / "latent_inversion.png"
    plt.savefig(output_path, dpi=150)
    plt.close(fig)
    print(f"Saved comparison to: {output_path}")


if __name__ == "__main__":
    main()